 source_code_paths=ARRAY['features/feature04/engine.py','features/feature04/pipeline.py','features/feature04/backfill.py','verification/feature04/FULL_BACKFILL.md','FEATURE04_TECHNICAL_INDICATOR.md']::text[],update_rule='Manual bounded refresh or explicitly authorized serial full-history per-ticker backfill; source corrections require chronological replay through output end. No scheduler.',updated_at=clock_timestamp()
